/**
 * Yorvyn — Ara 3D Gen Animation Controller
 * 
 * Reusable animation controller for rigged 3D human avatars generated by Ara 3D Gen.
 * Provides smooth crossfading, one-shot emote triggers, looping state management,
 * and automatic return-to-idle behavior without conflicting with orbit controls or mesh swaps.
 */

import * as THREE from 'three';

export interface PlayClipOptions {
  loop?: boolean;
  crossfadeDuration?: number;
  clampWhenFinished?: boolean;
  onComplete?: () => void;
}

export class AraAnimationController {
  private mixer: THREE.AnimationMixer | null = null;
  private actions: Map<string, THREE.AnimationAction> = new Map();
  private availableClips: Map<string, THREE.AnimationClip> = new Map();
  private currentAction: THREE.AnimationAction | null = null;
  private currentClipName: string | null = null;
  private onFinishedCallback: ((e: any) => void) | null = null;
  private pendingReturnTimeout: any = null;

  /**
   * Initializes the controller on a root Object3D (e.g. gltf.scene) using genuine AnimationClips.
   */
  init(root: THREE.Object3D, clips: THREE.AnimationClip[]): void {
    this.dispose();

    if (!clips || clips.length === 0) {
      console.warn('[AraAnimationController] No animation clips provided to controller');
      return;
    }

    this.mixer = new THREE.AnimationMixer(root);
    this.actions.clear();
    this.availableClips.clear();

    clips.forEach(clip => {
      this.availableClips.set(clip.name.toLowerCase(), clip);
      const action = this.mixer!.clipAction(clip);
      this.actions.set(clip.name.toLowerCase(), action);
    });

    console.log('[AraAnimationController] Initialized with real animation clips:', 
      clips.map(c => `${c.name} (${c.duration.toFixed(2)}s)`)
    );

    // Mixer finished listener for one-shot transitions (e.g. Wave -> Idle, Cheer -> Idle)
    this.onFinishedCallback = (e: any) => {
      if (e.action === this.currentAction && this.currentClipName !== 'idle') {
        this.returnToIdle(0.4);
      }
    };
    this.mixer.addEventListener('finished', this.onFinishedCallback);
  }

  /**
   * Returns a list of real animation clip names available in the loaded 3D model.
   */
  getAvailableClipNames(): string[] {
    return Array.from(this.availableClips.values()).map(c => c.name);
  }

  /**
   * Checks whether a specific clip exists in the loaded character model.
   */
  hasClip(name: string): boolean {
    return this.resolveAction(name) !== null;
  }

  /**
   * Resolves a clip action by exact name, normalized key, or common aliases.
   */
  private resolveAction(name: string): { action: THREE.AnimationAction; clip: THREE.AnimationClip } | null {
    if (!name) return null;
    const lower = name.toLowerCase().trim();

    // Direct match
    if (this.actions.has(lower) && this.availableClips.has(lower)) {
      return { action: this.actions.get(lower)!, clip: this.availableClips.get(lower)! };
    }

    // Substring / alias resolution
    for (const [key, action] of this.actions.entries()) {
      const clip = this.availableClips.get(key)!;
      if (
        key === lower ||
        key.includes(lower) ||
        lower.includes(key) ||
        (lower === 'turn' && (key.includes('turn') || key.includes('360'))) ||
        (lower === 'pose' && (key.includes('turn') || key.includes('idle')))
      ) {
        return { action, clip };
      }
    }

    return null;
  }

  /**
   * Plays an animation clip with optional crossfade and looping configuration.
   */
  play(clipName: string, options: PlayClipOptions = {}): boolean {
    if (!this.mixer) {
      console.warn('[AraAnimationController] Mixer not initialized');
      return false;
    }

    if (this.pendingReturnTimeout) {
      clearTimeout(this.pendingReturnTimeout);
      this.pendingReturnTimeout = null;
    }

    const resolved = this.resolveAction(clipName);
    if (!resolved) {
      console.warn(
        `[AraAnimationController] Clip "${clipName}" not found in model.\n` +
        `Available clips: [${this.getAvailableClipNames().join(', ')}].\n` +
        `To include this clip, add it to bakeCharacterClips() in AraService.`
      );
      return false;
    }

    const { action, clip } = resolved;
    const isLoop = options.loop ?? (clipName.toLowerCase() === 'idle');
    const fadeDuration = options.crossfadeDuration ?? 0.35;

    if (this.currentAction === action && action.isRunning()) {
      return true; // Already actively playing
    }

    action.reset();
    if (isLoop) {
      action.setLoop(THREE.LoopRepeat, Infinity);
      action.clampWhenFinished = false;
    } else {
      action.setLoop(THREE.LoopOnce, 1);
      action.clampWhenFinished = !!options.clampWhenFinished;
    }

    if (this.currentAction && this.currentAction !== action) {
      this.currentAction.crossFadeTo(action, fadeDuration, true);
    }

    action.play();
    this.currentAction = action;
    this.currentClipName = clip.name.toLowerCase();

    // Fallback timer if mixer finished event is missed (e.g. tab backgrounded)
    if (!isLoop && options.onComplete) {
      this.pendingReturnTimeout = setTimeout(() => {
        options.onComplete?.();
      }, clip.duration * 1000);
    }

    return true;
  }

  /**
   * Plays an animation once (e.g. Wave, Cheer, Turn) then smoothly crossfades back to Idle.
   */
  playOneShot(clipName: string, returnTo: string = 'Idle', crossfadeDuration = 0.35): boolean {
    const resolved = this.resolveAction(clipName);
    if (!resolved) {
      console.warn(`[AraAnimationController] Cannot play one-shot: clip "${clipName}" is not exported.`);
      return false;
    }

    const played = this.play(clipName, {
      loop: false,
      crossfadeDuration,
      clampWhenFinished: false,
      onComplete: () => {
        this.returnToIdle(crossfadeDuration, returnTo);
      }
    });

    return played;
  }

  /**
   * Smoothly crossfades back to the Idle animation.
   */
  returnToIdle(crossfadeDuration = 0.4, idleName: string = 'Idle'): void {
    if (this.currentClipName === 'idle' && this.currentAction?.isRunning()) {
      return;
    }
    this.play(idleName, {
      loop: true,
      crossfadeDuration
    });
  }

  /**
   * Stops playback of all or current animation actions.
   */
  stop(): void {
    if (this.mixer) {
      this.mixer.stopAllAction();
    }
    this.currentAction = null;
    this.currentClipName = null;
  }

  /**
   * Advance mixer clock per render frame.
   */
  update(delta: number): void {
    if (this.mixer) {
      this.mixer.update(delta);
    }
  }

  /**
   * Gets the currently playing clip name.
   */
  getCurrentClipName(): string | null {
    return this.currentClipName;
  }

  /**
   * Cleans up mixer and event listeners.
   */
  dispose(): void {
    if (this.pendingReturnTimeout) {
      clearTimeout(this.pendingReturnTimeout);
      this.pendingReturnTimeout = null;
    }
    if (this.mixer && this.onFinishedCallback) {
      this.mixer.removeEventListener('finished', this.onFinishedCallback);
      this.mixer.stopAllAction();
    }
    this.mixer = null;
    this.actions.clear();
    this.availableClips.clear();
    this.currentAction = null;
    this.currentClipName = null;
  }
}

/** Global singleton instance for fashion studio animation orchestration */
export const araAnim = new AraAnimationController();
export const avatarAnimationController = araAnim;
